package com.changzheng.controller;
import com.changzheng.common.ApiResponse; import com.changzheng.entity.StepExchange; import com.changzheng.service.*; import com.changzheng.vo.MapDataVO; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/map") @RequiredArgsConstructor public class MapController {private final UserService users;private final MapService map;private final ExchangeService exchange; @GetMapping("/getAllData/{userId}") public ApiResponse<MapDataVO> get(@PathVariable Long userId){users.get(userId);return ApiResponse.success(map.get(userId));} @PutMapping("/exchangeSteps/{userId}") public ApiResponse<StepExchange> exchange(@PathVariable Long userId){users.get(userId);return ApiResponse.success(exchange.exchange(userId));}}
